test:
let o = topo_sort(4, &[(0,1),(0,2),(1,3),(2,3)]).unwrap();
    let idx = |x: usize| o.iter().position(|&v| v==x).unwrap();
    assert!(idx(0)<idx(1) && idx(0)<idx(2) && idx(1)<idx(3) && idx(2)<idx(3));
    assert!(topo_sort(3, &[(0,1),(1,2),(2,0)]).is_none());
    assert!(topo_sort(3, &[(0,1),(1,2)]).is_some());

let e = [(0,1,4),(0,2,1),(2,1,2),(1,3,1),(2,3,5)];
    assert_eq!(dijkstra(4,&e,0,3), Some(4));
    assert_eq!(dijkstra(4,&e,3,0), None);
    assert_eq!(dijkstra(4,&e,0,0), Some(0));

assert_eq!(calc("2^3^2"), 512);
    assert_eq!(calc("-2^2"), -4);
    assert_eq!(calc("2 + 3 * 4"), 14);
    assert_eq!(calc("(2 + 3) * 4"), 20);
    assert_eq!(calc("-(3 + 4)"), -7);
    assert_eq!(calc("2 * -3 + 10"), 4);
    assert_eq!(calc("100 / 5 / 2"), 10);

assert_eq!(is_match("aa","a"), false);
    assert_eq!(is_match("aa","a*"), true);
    assert_eq!(is_match("ab",".*"), true);
    assert_eq!(is_match("aab","c*a*b"), true);
    assert_eq!(is_match("mississippi","mis*is*p*."), false);
    assert_eq!(is_match("mississippi","mis*is*ip*."), true);

assert_eq!(word_break("leetcode", &["leet","code"]), true);
    assert_eq!(word_break("applepenapple", &["apple","pen"]), true);
    assert_eq!(word_break("catsandog", &["cats","dog","sand","and","cat"]), false);
